WFJ.Data.add("quest", {
  [79007] = { "……それと、君が見つけたあのメモ", "焦げたメモの燃えかすだけが唯一の手がかりだ。", "<燃えさしのかすかな輝きが暗くなっていく中、あなたは最近焚かれた火の跡に行き当たる。\n\n散らばった食料の中に、焼け焦げて火ぶくれのできたメモが見つかった。>\n\n「燃えるものすべてが失われるわけではない。双子の地を見つけ、その場所を見つけよ」", nil, nil, 0x5aedabd1, 0xb4126cf2, 0x9304bba3, nil, nil, "...mm" },
  [79008] = { "……それと、君が見つけたあのメモ", "焦げたメモの燃えかすだけが唯一の手がかりだ。", "<燃えさしのかすかな輝きが暗くなっていく中、あなたは最近焚かれた火の跡に行き当たる。\n\n散らばった食料の中に、焼け焦げて火ぶくれのできたメモが見つかった。>\n\n「燃えるものすべてが失われるわけではない。双子の地を見つけ、その場所を見つけよ」", nil, "またしても焼け焦げた死体の残骸に出くわしたあなたは、木の板に留められた書き付けに目を留めた。", 0x5aedabd1, 0xb4126cf2, 0x9304bba3, nil, 0xf149b5be, "...m." },
  [79090] = { "侵入者の撃退", "Warsong Outrider Markを、AshenvaleのMoonwellの拠点にいるPriestess of the MoonのFelore Moonrayのところへ持って行って下さい。", "Warsong Outridersの何人かは倒れたが、戦いはまだ激しく続いている……", nil, nil, 0xd7957bbe, 0xdef0139e, 0x793d0d29, nil, nil, "...mm" },
  [79091] = { "Archmage Antonidas: The Unabridged Autobiography", nil, nil, "私たちのコレクションに加える品を、何か持ってきてくれたか？", "ありがとうございます、{name}。これはIronforgeの図書館のものだと言うのですか？……まあ、なくなっても気づかれないでしょう。\n\n図書館の役に立ちそうな魔法の書物をほかにも見つけたら、ぜひ私のところへ持ってきてください。", 0x009cff45, nil, nil, 0x1400fbf0, 0xba293cb0, ".mm.." },
  [79092] = { "Archmage Theocritus' Research Journal", nil, nil, "私たちのコレクションに加える品を、何か持ってきてくれたか？", "ありがとうございます、{name}。あなたの尽力で私たちの知識は広がります。\n\n図書館の役に立ちそうな魔法の書物をほかにも見つけたら、ぜひ私のところへ持ってきてください。", 0x276fbac6, nil, nil, 0x1400fbf0, 0xe184a784, ".mm.." },
  [79093] = { "Rumi of Gnomeregan: The Collected Works", nil, nil, "私たちのコレクションに加える品を、何か持ってきてくれたか？", "ありがとうございます、{name}。あなたの尽力で私たちの知識は広がります。\n\n図書館の役に立ちそうな魔法の書物をほかにも見つけたら、ぜひ私のところへ持ってきてください。", 0x24c45025, nil, nil, 0x1400fbf0, 0xe184a784, ".mm.." },
  [79094] = { "The Lessons of Ta'zo", nil, nil, nil, nil, 0xfaffd003, nil, nil, nil, nil, ".mmmm" },
  [79095] = { "The Apothecary's Metaphysical Primer", nil, nil, nil, nil, 0xcbb1ebc8, nil, nil, nil, nil, ".mmmm" },
  [79096] = { "Ataeric: On Arcane Curiosities", nil, nil, nil, nil, 0x673b8f25, nil, nil, nil, nil, ".mmmm" },
  [79097] = { "Baxtan: On Destructive Magics", nil, nil, "私たちのコレクションに加える品を、何か持ってきてくれたか？", "ありがとうございます、{name}。あなたの尽力で私たちの知識は広がります。\n\n図書館の役に立ちそうな魔法の書物をほかにも見つけたら、ぜひ私のところへ持ってきてください。", 0x3e745b06, nil, nil, 0x1400fbf0, 0xe184a784, ".mm.." },
  [79098] = { "森を一掃せよ！", "Silverwing Sentinel Charmを、AshenvaleのBonfireの拠点にいるFar SeerのKazragoreのところへ持って行って下さい。", "こいつは討ち取ったが、腹立たしいallianceどもはまだ戦いを続けている……このお守りは何だ？", nil, nil, 0x47bae5fc, 0x072ac677, 0x0d462d55, nil, nil, "...mm" },
  [79192] = { "踏み石", "板からメモを引きはがし、走り書きを読む。", "メモはこう始まっている。「Missionの話じゃ、二人ともNew Plagueの配達をしてたそうだ。俺にはただの薬剤師の事故にしか見えないがね。安全な場所で話したいなら、BarrensとDesolaceの間の山にある俺の居心地のいい隠れ場所を見つけな」", nil, "辺境の冒険者も傭兵も、ここで野営しているのは間違いない。風にはためくメモの端が目に留まり、あなたはそれに手を伸ばした。", 0x9dd88a3c, 0x42f58b36, 0x18dc9772, nil, 0xf47f0ef5, "...m." },
  [79229] = { "街道の強盗", "荒らされた野営地のことを知っている者をDesolaceで見つける。", "目の前の野営地は凄惨な有様だ。遺体から判断するに、犠牲者は人間二人とドワーフ一人だ。骨に残る傷跡は獰猛な襲撃を物語っているが、物資が略奪されていることから、獣の仕業ではないことが分かる。傷はcentaurの武器とも一致しない。\n\nこの地に詳しい、経験豊富な漁り屋なら、何か分かるかもしれない。", nil, nil, 0x3d1fe3af, 0xab3965fc, 0xaa70b186, nil, nil, "...mm" },
  [79235] = { "逃亡中", "Desolaceの略奪者を一人見つける。", "あんたが言うような現場なら、いくつか見つけたよ、{name}。いつも人間とドワーフの野営地だ。隊商の間じゃ、Hordeの略奪者の一団の仕業だって噂だ。犠牲者や襲撃の残忍さからして、ありそうな話だな。\n\nどうやらAllianceの元帥に追い詰められて、その盗賊どもはDesolaceから逃げ出したらしい。\n\nそいつらの一人を追うつもりなら、Booty Bayを当たってみるといい。港にはいつも怪しい連中が出入りしてる。どこかへ行く船に乗ろうとしてる奴を捕まえられるかもな。", nil, nil, 0xf2526006, 0x70272baf, 0xd8c30f25, nil, nil, "...mm" },
  [79236] = { "チェリーで考えを聞かせて？", "Booty BayのTokalにCherry Grogを届け、彼女の話の続きを聞く。", "元帥の仲間か？いや、そうは見えないな。\n\nお前が聞いた噂は半分しか本当じゃない。確かに俺たちは人間とドワーフの野営地を荒らしていたが、Hordeのためにやっていたわけじゃない。個人的に雇われていたんだ。\n\ngrogをおごってくれたら、全部話してやるよ。", nil, nil, 0xd1679730, 0xaf00f503, 0xc6745099, nil, nil, "...mm" },
  [79242] = { "盗賊に仁義なし", "Arathi Highlandsの海岸でIllari Duskfeatherを見つけ、彼女の盗品の隠し場所に入れてもらう。", "さっきの話の続きだが……\n\n俺たちのボスはHordeの者じゃなかった。Illari Duskfeatherという名のナイトエルフの女だ。野営地の情報を流してくれて、戦利品もほとんど俺たちに持たせてくれた。自分では珍しい掘り出し物をいくつか取っておいただけだ。\n\nだが、元帥に追われるようになると、あの女は俺たちを見捨てた。目的は知らんが、俺たちは身代わりに仕立てられたんだと思う。\n\n俺は復讐するような柄じゃないが、誰かがあいつを追い詰めるのを止める気もない。あいつを探してるなら、Arathiの海岸に隠れ家があると前に言ってたぞ。", nil, nil, 0x4053d811, 0x8394b9d9, 0xbe882b9e, nil, nil, "...mm" },
  [79358] = { "嵐、大地、そして炎", "Arathi HighlandsのVeyric ThunderhameのためにTwisted Fire Totemsを$N1個、Twisted Earth Totemsを$N2個、Twisted Air Totemsを$N3個、Twisted Water Totemsを$N4個集める。", "Thousand Needlesを水浸しにするなんて、並大抵のことじゃねえぞ、{name}。わし自身がエレメントの怒りを感じとらなけりゃ、とても信じられんかったろう。だが、現にこうなっとる。\n\nエレメントを無責任に武器にしたのはquilboarが最初じゃねえし、最後でもねえだろう。わしらで対抗の儀式を用意するなら、この歪んだエレメントをもっとよく知る必要がある。この本を持っていけ。Azerothの数多の住人たちと、彼らがシャーマンの術をどう実践しとるかが詳しく書いてある。\n\nそいつらから学べれば、解決策が見つかるかもしれん。", nil, nil, 0x7f68981f, 0xdaa7679c, 0xac92210f, nil, nil, "...mm" },
  [79360] = { "精霊の助け", "Razorfen KraulでCharlga Razorflankを倒し、quilboarの計画に関する情報を集める。", "エレメントを極めた今、あなたには彼らへの責務があり、それはすなわちAzerothそのものへの責務でもあります。私たちは彼らに助けを請うのであって、その力を要求するのではありません。あなたが授かった恩を返す時が来ました。その方法にも心当たりがあります。\n\nquilboarは自らの目的のためにエレメントを歪め、この地の内側へと勢力を広げているようです。彼らのkraulへ赴き、何を企んでいるにせよ、それを終わらせてください。この地は守られねばなりません。", nil, nil, 0x3a904965, 0xd3648ee8, 0x6cf45d3c, nil, nil, "...mm" },
  [79361] = { "嵐、大地、そして炎", "Thousand NeedlesのPrate CloudseerのためにTwisted Fire Totemsを$N1個、Twisted Earth Totemsを$N2個、Twisted Air Totemsを$N3個、Twisted Water Totemsを$N4個集める。", "quilboarが歪んだシャーマンの術でThousand Needlesを水に沈めようとしている、と？ほとんど想像もつかないことですが、あの者たちを甘く見てはならないことは、あなた自身が見てきたはずです。\n\n本当は、あなたの修行をじっくり続けたかったのですが、今はその時間がありません。この地には、味方も敵も含め、多くの異なる生き物が暮らしています。そのどれも、そのような運命に値しません。行動しなければ。\n\nこの書物を持って行きなさい。学ぶためのものでしたが、今や迫り来る嵐を鎮める鍵となるかもしれません。", nil, nil, 0x7f68981f, 0xcef55429, 0x1556610d, nil, nil, "...mm" },
  [79362] = { "Grant's Shield", "Raven Hill Cemeteryの骸骨のどれかからGrant's Maceを見つけ、詳しい情報を聞きにDarkshireのSirra Von'Indieのところへ戻る。", "Raven Hillの英雄にしてValor家の父、Grant Valorの霊が残した盾。\n\nGrantの霊が今もアンデッドと戦い続けているのなら、彼のやり残したことは、Raven Hill Cemeteryで彼に傷を負わせたscourgeを倒すことなのかもしれない。おそらく、今も彼のmaceが突き刺さったままの相手だろう。", nil, nil, 0x55951b8a, 0xe684af82, 0x80fde678, nil, nil, "...mm" },
  [79363] = { "Silvia's Sword", "Addle's SteadでDefias Night Bladeを$N1体とDefias Enchanterを$N2体倒し、詳しい情報を聞きにDarkshireのSirra Von'Indiのところへ戻る。", "民とその家を守ることに生涯を捧げた、Raven Hillの衛兵Silvia Valorの霊が残した剣。\n\nSilviaの霊が今も農場を訪れているのなら、彼女のやり残したことは、Raven Hillの南にあるAddle's Steadに住み着いたdefiasを追い払うことなのかもしれない。", nil, nil, 0xf920a622, 0xef4e0f85, 0x1497337f, nil, nil, "...mm" },
  [79364] = { "空を見張る", "Thousand NeedlesのPrate Cloudseerと話す。", "あなたが見つけたメモによると、RazormaneはThousand Needlesに潜り込み、何やら人目につかない儀式を行っているそうです。荒れ狂う嵐と、満ちてくる潮……\n\nquilboarは、エレメントを歪めることに執念を燃やしたシャーマン、Hirzekから学んだ残酷な妖術を使っているに違いありません。峡谷を水没させるつもりなら、恐ろしいほど強大なエレメントの力が必要なはずです。\n\n私たちにはこれに対処する備えがありませんが、あなたほど強力なシャーマンなら何か考えがあるでしょう。仲間のもとへ戻り、答えが見つからないか確かめてください。", nil, nil, 0x4fb9105f, 0x3f460f76, 0xb3c28958, nil, nil, "...mm" },
  [79365] = { "翼の下に風を受けて", "Thousand NeedlesのFreewind PostにいるRau Cliffrunnerのもとへ戻る。", "ほらよ、お前に要るのはSquall-breakers Potionだ。嵐のエレメントから身を守るためにこれを飲むんだ。だが、効き目は少しの間しか続かねえってことを忘れるなよ。\n\nさあ行け、困ってる仲間のところへ戻るんだ。俺がしてやれることはもうねえ。", nil, nil, 0xeaffbe14, 0xaeb48077, 0xbd5b5b19, nil, nil, "...mm" },
  [79366] = { "我が呼び声に耳を傾けて", "Twisted Totemsを使い、quilboarの儀式を終わらせる。", "歪んだトーテムを手に入れた今、それを振るって、quilboarが呼び寄せている堕落したエレメンタルを召喚しなければなりません。彼らを倒してこの地を浄化し、Razormaneのおぞましい儀式を終わらせたら、Rau Cliffrunnerに成果を報告してください。\n\n浄化は西にある蒸気の泉から始めるといいでしょう。あの辺りはどのエレメントにも満ちています。ですが気をつけて、{name}。quilboarは、あなたが計画を邪魔するのを黙って見てはいないでしょう。", nil, nil, 0xb87aaede, 0x5eafbe6d, 0x6a7313ec, nil, nil, "...mm" },
  [79442] = { "嵐の武器", "Eye of the TempestをAlterac MountainsのBath'rah the Windwatcherに届ける。", "我らの民はいくら感謝してもしきれないが、このeyeは私には使い道がない。Alterac山脈に、嵐のエレメンタルの魔法に目が利く年老いたシャーマンがいると聞いている。彼なら何かを作ってくれるかもしれない。", nil, nil, 0x578d0b90, 0x5da19497, 0xb252f1db, nil, nil, "...mm" },
  [79535] = { "Basilisks: Should Petrification be Feared?", nil, nil, nil, nil, 0xa30fcfac, nil, nil, nil, nil, ".mmmm" },
  [79536] = { "図書館の偉大なる友", nil, nil, nil, nil, 0xf10ee12c, nil, nil, nil, nil, ".mmmm" },
  [79624] = { "誰でも料理はできる", "Illegible Recipeを読めるogreを見つける。", "このrecipeは、何かの肉料理のもののようだ。あなたには読めない言語で書かれている。出どころと内容からして、Ogreの言葉というのが最も有力な推測だ。\n\nOgreはたいてい料理好きではないが、そういう趣味を持つ者を知っていれば、そのrecipeを訳してもらえるだろう。", nil, nil, 0x6efd80be, 0xe9aa48ab, 0xfc4de398, nil, nil, "...mm" },
  [79637] = { "Ticking Present", nil, nil, nil, nil, 0xd9f880a5, nil, nil, nil, nil, ".mmmm" },
  [79731] = { "トロールの巻物", "巻物の謎を解く。それが済んだら、Hemet Nesingwaryがその話を聞きたがるかもしれない。", "<古代の文字が、目の前で言葉へと変わっていく。>\n\nZul'Kundaの噴水に聖なる泉の水が流れるとき、神々は祝福を与える。", nil, nil, 0xfd4a85b9, 0x4e2761f1, 0x1382b37e, nil, nil, "...mm" },
  [79947] = { "Geomancy: The Stone-Cold Truth", nil, nil, nil, nil, 0x19d978d8, nil, nil, nil, nil, ".mmmm" },
  [79948] = { "Defensive Magics 101", nil, nil, nil, nil, 0x5bc13f46, nil, nil, nil, nil, ".mmmm" },
  [79949] = { "A Web of Lies: Debunking Myths and Legends", nil, nil, nil, nil, 0xefc18e04, nil, nil, nil, nil, ".mmmm" },
  [79950] = { "Demons and You", nil, nil, nil, nil, 0x6fe9a1ef, nil, nil, nil, nil, ".mmmm" },
  [79951] = { "Mummies: A Guide to the Unsavory Undead", nil, nil, nil, nil, 0x99295356, nil, nil, nil, nil, ".mmmm" },
  [79952] = { "RwlRwlRwlRwl!", nil, nil, nil, nil, 0x6bc7959f, nil, nil, nil, nil, ".mmmm" },
  [79974] = { "濡れ仕事", "土から覗いている伝令の鞄の埃を払うと、中の物資の間に羊皮紙が挟まっているのが見つかる。", "「いざという時に急いで逃げなきゃならない場合に備えて、近くに予備の蓄えを置いておくのが好きなんだ。\n\nこの山腹の斜面は実に美しくて、時の滝から彫り出されたとでも言いたくなるほどだ。\nあれが鷲の巣だ。お前が探しているのはあれだよ」", nil, "Dwarven Engineering、いつ見ても驚異だ。", 0x9c808653, 0x9e139b4e, 0x631c42d4, nil, 0xb4a31145, "...m." },
  [79975] = { "Eagle's Fist", "水しぶきが辺りを湿らせ、眺めは素晴らしい。", "<道具箱の中に、丁寧に折りたたまれた手紙が見つかった。>\n\n「ここからなら、ちゃんとした道具さえあれば、思いのままに事を運べる。パラシュートグライダーで飛び立つには絶好の場所だ。\n\nEagle and Fistへの忠誠を最もよく果たすには、距離を置く必要がある。このバリケードもかつてはもっと良い時代があった。かつて守っていたOld Kingdomsと同じようにな。だが、俺は決してこれを見捨てはしない」", nil, "焚き火には新しく薪がくべられているが、急いで立ち去った形跡がはっきりと残っている。", 0xa1fb6a7a, 0xb9a33603, 0x322bb447, nil, 0x98322f53, "...m." },
  [79976] = { "きっとここだ", "ここに誰がいたにせよ、ちょうど行き違いになったようだ。", "「そういうわけで、仕事をまた地下に戻すことにした。悪い連中の手に渡らないようにな」\n\n<紙はちょうどこの伝言が収まる大きさに破り取られている。これが書き手から読む最後の言葉なのか、それとも次の隠れ家への手がかりなのか、あなたには分からない。きちんと留められていなかった寝袋が、あなたの足元へ広がってくる……>", nil, "さまざまな装備に厚手の帆布がかぶせて巻かれている。あなたは荷物を遠慮なくいただいた。", 0x3d8d005f, 0x5d8a5aef, 0xb96b3437, nil, 0x72a36d26, "...m." },
  [79980] = { "争奪戦", "待ち受けているものを見つけてください。", "「悪くないだろう？ これを読んでるってことは、俺の蓄えはまだそこにあるってことだ。真北へ100歩進め。険しい崖を下る時に足首を折るなよ。やっていけるだけの量はあるはずだ」", nil, "あなたは地面から使者の鞄を引っ張り出した。補給品と一緒に、汚れた羊皮紙が詰め込まれている。", 0x51393b00, 0xecbb9528, 0x76de52ab, nil, 0x85208ab7, "...m." },
})
